{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table thd-pharma-wh.maplemonk.thd_pharma_inventory_fact_items as WITH daily_sku_sales AS ( SELECT CAST(order_date AS DATE) AS date_day, upper(commonsku) as sku, SUM(quantity) AS daily_quantity, safe_divide(sum(ifnull(selling_price,0)),SUM(ifnull(quantity,0))) as asp from thd-pharma-wh.MAPLEMONK.thd_pharma_wh_SALES_CONSOLIDATED s WHERE commonsku is not null and not(order_status like any (\'%cancel%\',\'%return%\')) GROUP BY 1,2 ), daily_inventory_snapshot AS ( SELECT DATE(DATETIME_ADD(PARSE_DATETIME(\'%Y-%m-%d %H:%M:%S\',i.Report_Generated_Date), Interval 3 hour)) date_day, replace(i.sku,\'`\',\'\') sku, sum(cast(Available_Quantity as INT64)) as inventory_that_day, CASE WHEN ifnull(sum(cast(Available_Quantity as INT64)),0) > 0 THEN 1 ELSE 0 END AS has_inventory, CASE WHEN ifnull(sum(cast(Available_Quantity as INT64)),0) < 1 THEN 1 ELSE 0 END AS is_oos FROM thd-pharma-wh.maplemonk.easyecom_4thd_easyecom_inventory_snapshot i GROUP BY 1,2 ORDER BY 1 DESC ), all_sku_dates AS ( SELECT DISTINCT c.date_day, d.sku, FROM daily_inventory_snapshot AS d CROSS JOIN ( SELECT date_day FROM UNNEST(GENERATE_DATE_ARRAY(DATE \'2026-01-01\', CURRENT_DATE())) AS date_day ) AS c ), sales_metrics AS ( SELECT a.date_day, a.sku, COALESCE(s.daily_quantity, 0) AS daily_quantity, s.asp, COALESCE(i.has_inventory, 0) AS has_inventory_today, inventory_that_day, ifnull(i.is_oos, 1) AS is_oos_today, SUM(COALESCE(s.daily_quantity, 0)) OVER (PARTITION BY a.sku ORDER BY a.date_day ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS L7_day_sales, SUM(COALESCE(s.daily_quantity, 0)) OVER (PARTITION BY a.sku ORDER BY a.date_day ROWS BETWEEN 29 PRECEDING AND CURRENT ROW) AS L30_day_sales, SUM(COALESCE(s.daily_quantity, 0)) OVER (PARTITION BY a.sku ORDER BY a.date_day ROWS BETWEEN 59 PRECEDING AND CURRENT ROW) AS L60_day_sales, SUM(COALESCE(s.daily_quantity, 0)) OVER (PARTITION BY a.sku ORDER BY a.date_day ROWS BETWEEN 89 PRECEDING AND CURRENT ROW) AS L90_day_sales, SUM(COALESCE(s.daily_quantity, 0)) OVER (PARTITION BY a.sku, DATE_TRUNC(a.date_day, MONTH) ORDER BY a.date_day) AS MTD_day_sales, SUM(COALESCE(i.has_inventory, 0)) OVER (PARTITION BY a.sku ORDER BY a.date_day ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS inventory_days_7, SUM(COALESCE(i.has_inventory, 0)) OVER (PARTITION BY a.sku ORDER BY a.date_day ROWS BETWEEN 29 PRECEDING AND CURRENT ROW) AS inventory_days_30, SUM(COALESCE(i.has_inventory, 0)) OVER (PARTITION BY a.sku ORDER BY a.date_day ROWS BETWEEN 59 PRECEDING AND CURRENT ROW) AS inventory_days_60, SUM(COALESCE(i.has_inventory, 0)) OVER (PARTITION BY a.sku ORDER BY a.date_day ROWS BETWEEN 89 PRECEDING AND CURRENT ROW) AS inventory_days_90, SUM(IFNULL(i.is_oos, 0)) OVER (PARTITION BY a.sku ORDER BY a.date_day ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS oos_days_7, SUM(IFNULL(i.is_oos, 0)) OVER (PARTITION BY a.sku ORDER BY a.date_day ROWS BETWEEN 29 PRECEDING AND CURRENT ROW) AS oos_days_30, SUM(IFNULL(i.is_oos, 0)) OVER (PARTITION BY a.sku ORDER BY a.date_day ROWS BETWEEN 59 PRECEDING AND CURRENT ROW) AS oos_days_60, SUM(IFNULL(i.is_oos, 0)) OVER (PARTITION BY a.sku ORDER BY a.date_day ROWS BETWEEN 89 PRECEDING AND CURRENT ROW) AS oos_days_90, SUM(IFNULL(i.is_oos, 0)) OVER (PARTITION BY a.sku, DATE_TRUNC(a.date_day, MONTH) ORDER BY a.date_day) AS oos_days_mtd FROM all_sku_dates AS a LEFT JOIN daily_sku_sales AS s ON a.date_day = s.date_day AND a.sku = s.sku LEFT JOIN daily_inventory_snapshot AS i ON a.date_day = i.date_day AND a.sku = i.sku order by 1 desc ) SELECT date_day as data_fetch_date, s.sku, s.asp, date_diff(date_day,created_at,day) as days_since_creation, case when date_diff(date_day,created_at,day) between 0 and 90 then \'NPD\' else \'Old SKU\' end as sku_status, p.product_name, p.category, p.size, p.color, p.image, p.product_type, s.daily_quantity, s.has_inventory_today, s.inventory_that_day as available_inventory, MTD_day_sales as sold_quantity_mtd, L7_day_sales sold_quantity_7_days, L30_day_sales sold_quantity_30_days, L60_day_sales sold_quantity_60_days, L90_day_sales sold_quantity_90_days, inventory_days_7, inventory_days_30, inventory_days_60, inventory_days_90, oos_days_7, oos_days_30, oos_days_60, oos_days_90, oos_days_mtd, (L7_day_sales/7 * 0.4 + L30_day_sales/30 * 0.3 + L60_day_sales/60 * 0.2 + L90_day_sales/90 * 0.1) as weighted_drr, rank() over (partition by date_day order by (L7_day_sales/7 * 0.4 + L30_day_sales/30 * 0.3 + L60_day_sales/60 * 0.2 + L90_day_sales/90 * 0.1) desc) as rank FROM sales_metrics s LEFT JOIN (select * from (select product_name, category, size, color, mrp, cost as cogs, tax_rate, image, product_type, commonsku, created_at, row_number()over (partition by commonsku order by length(ifnull(commonsku,\'\')) desc) rw from thd-pharma-wh.maplemonk.ozone_pharma_sku_master ) where rw = 1 ) p on upper(p.commonsku) = upper(s.sku) where upper(s.sku) like \'F%\' or upper(s.sku) like \'T%\' ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            